#!/bin/bash
# Usage: bash tools/perf/serve.sh (after dotnet publish + local DB + TLS setup; see audit reproduction)
set -euo pipefail
image=mcr.microsoft.com/dotnet/aspnet:10.0-noble-chiseled-extra@sha256:00e0ad6a7ef8c0c1391b87f05c7ac757a15740455688f2bfcd146a3f4b987efd
docker run -d --name plate-perf-app --entrypoint dotnet --read-only --memory 256m --cpus 1 --cap-drop ALL --security-opt no-new-privileges --pids-limit 200 --tmpfs /tmp:size=64m -p 127.0.0.1:5443:8443 --add-host host.docker.internal:host-gateway -v /private/tmp/plate-perf-publish:/app:ro -v /private/tmp/plate-perf-tls:/tls:ro -v /private/tmp/plate-perf-keys:/keys -v /private/tmp/plate-perf-dotnet:/tools:ro -e ASPNETCORE_ENVIRONMENT=Production -e ASPNETCORE_URLS=https://+:8443 -e ASPNETCORE_Kestrel__Certificates__Default__Path=/tls/cert.pfx -e ASPNETCORE_Kestrel__Certificates__Default__Password=perf-local-only -e DataProtection__KeysPath=/keys -e 'ConnectionStrings__Default=Host=host.docker.internal;Port=55432;Database=gym_perf;Username=gym;Password=perf-local-only;Maximum Pool Size=8' -e OpenRouter__BaseUrl=http://127.0.0.1:9/ -e RateLimits__AiParsePerWindow=100000 -e RateLimits__AiLabelPerWindow=100000 -e Logging__LogLevel__Default=Warning -w /app "$image" Plate.Web.dll
